import { anything, parseKerML, withQualifiedName } from "../../../testing";
import { Feature } from "../../../generated/ast";

test("feature chains allow qualified feature names in between chain parts", async () => {
    const result = await parseKerML(`
    class A {
        feature a {
            class B {
                feature b;
            }
        }
    }
    feature c chains A::a.B::b;`);

    expect(result).toParseKerML({
        children: [
            ...anything(1),
            {
                target: {
                    $type: Feature,
                    ...withQualifiedName("c"),
                },
            },
        ],
    });
});

test.failing("non-feature name in a chain fails to parse", async () => {
    return expect(`
    class A {
        class a {
            class B {
                feature b;
            }
        }
    }
    feature c chains A::a.B::b;`).toParseKerML({}, { buildOptions: { validationChecks: "all" } });
});

