describe("prettier conformance", () => {
    it("should break groups like prettier", () => {
        // https://prettier.io/playground/#N4Igxg9gdgLgprEAuc0DOMAEBDTBeTACmwEolMAVfAPkwEYAGJkAGhAgAcYBLdZUbACdBEAO4AFIQjTIQ2ADajsATxlsARoOxgA1nBgBlbAFs4AGW5Q4yAGYK0cDVt36DHbZYDmyGIICujiAOxtw+-
        const doc = [
            group([
                text("const"),
                text(" "),
                group([
                    group(text("a")),
                    text(" ="),
                    group(indent(line), { id: "assignment" }),
                    lineSuffixBoundary,
                    indentIfBreak(
                        group([
                            group(
                                group([
                                    text("("),
                                    indent([softline, text("a")]),
                                    ifBreak(text(","), literals.emptytext),
                                    softline,
                                    text(")"),
                                    text(":"),
                                    text(" "),
                                    text("T"),
                                ]),
                                { id: "arrow-chain" }
                            ),
                            text(" =>"),
                            group(indent([line, text("1000")])),
                        ]),
                        { groupId: "assignment" }
                    ),
                ]),
                indent([]),
                text(";"),
            ]),
            hardline,
        ];

        expect(print(doc, { lineWidth: 14, tabWidth: 2 })).toEqual(`const a = (
  a,
): T => 1000;
`);
    });
});

